create extension if not exists pgcrypto;
create table players(id uuid primary key default gen_random_uuid(), display_name text not null check(char_length(display_name) between 2 and 24), avatar text not null default 'a1', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table guest_sessions(id uuid primary key default gen_random_uuid(), player_id uuid not null references players(id) on delete cascade, token_hash text not null unique, created_at timestamptz not null default now(), last_seen_at timestamptz not null default now());
create table challenge_packs(id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, status text not null default 'published' check(status in('draft','published','retired')), created_at timestamptz not null default now());
create table questions(id uuid primary key default gen_random_uuid(), pack_id uuid not null references challenge_packs(id) on delete cascade, position int not null, type text not null check(type in('trivia','logic','emoji','memory','pattern','riddle')), category text not null, difficulty int not null check(difficulty between 1 and 3), prompt text not null, options jsonb not null, correct_index int not null, explanation text not null, status text not null default 'published', version int not null default 1, unique(pack_id,position));
create table daily_challenges(challenge_date date not null, version int not null default 1, pack_id uuid not null references challenge_packs(id), published_at timestamptz not null default now(), primary key(challenge_date,version));
create table rooms(id uuid primary key default gen_random_uuid(), code text not null unique, host_player_id uuid not null references players(id), mode text not null, status text not null default 'waiting' check(status in('waiting','playing','completed','expired','voided')), max_players int not null default 2 check(max_players between 2 and 6), expires_at timestamptz not null, created_at timestamptz not null default now());
create table room_players(room_id uuid references rooms(id) on delete cascade, player_id uuid references players(id) on delete cascade, ready boolean not null default false, joined_at timestamptz not null default now(), primary key(room_id,player_id));
create table matches(id uuid primary key default gen_random_uuid(), room_id uuid references rooms(id) on delete set null, pack_id uuid not null references challenge_packs(id), status text not null default 'playing' check(status in('playing','completed','voided')), started_at timestamptz not null default now(), finished_at timestamptz, idempotency_key text not null unique);
create table answers(match_id uuid references matches(id) on delete cascade, question_id uuid references questions(id), player_id uuid references players(id) on delete cascade, choice int not null, points int not null default 0, elapsed_ms int not null, created_at timestamptz not null default now(), primary key(match_id,question_id,player_id));
create table match_results(match_id uuid references matches(id) on delete cascade, player_id uuid references players(id) on delete cascade, score int not null, correct int not null, rank int not null, primary key(match_id,player_id));
create index on match_results(player_id, match_id);
create table friend_challenges(id uuid primary key default gen_random_uuid(), code text not null unique, challenger_id uuid not null references players(id) on delete cascade, pack_id uuid not null references challenge_packs(id), status text not null default 'open' check(status in('open','completed','expired')), expires_at timestamptz not null, created_at timestamptz not null default now());
create table challenge_attempts(id uuid primary key default gen_random_uuid(), player_id uuid not null references players(id) on delete cascade, daily_date date, friend_challenge_id uuid references friend_challenges(id) on delete cascade, score int not null, correct int not null, total_ms int not null, ranked boolean not null default false, idempotency_key text not null unique, created_at timestamptz not null default now());
create unique index one_ranked_daily on challenge_attempts(player_id,daily_date) where ranked;
create index daily_lb on challenge_attempts(daily_date, score desc, total_ms asc, created_at asc) where ranked;
create index player_history on challenge_attempts(player_id, created_at desc);
create table achievements(code text primary key, title text not null, description text not null);
create table player_achievements(player_id uuid references players(id) on delete cascade, code text references achievements(code), earned_at timestamptz not null default now(), primary key(player_id,code));
create table community_submissions(id uuid primary key default gen_random_uuid(), author_id uuid not null references players(id) on delete cascade, title text not null check(char_length(title)<=80), type text not null, category text not null, prompt text not null check(char_length(prompt)<=300), answer text not null check(char_length(answer)<=100), explanation text not null check(char_length(explanation)<=300), difficulty int not null check(difficulty between 1 and 3), status text not null default 'pending' check(status in('pending','approved','rejected','removed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index on community_submissions(status, created_at);
create table moderation_reports(id uuid primary key default gen_random_uuid(), submission_id uuid not null references community_submissions(id) on delete cascade, reporter_id uuid references players(id) on delete set null, reason text not null check(char_length(reason)<=300), created_at timestamptz not null default now());
create table moderation_actions(id uuid primary key default gen_random_uuid(), submission_id uuid not null references community_submissions(id) on delete cascade, action text not null check(action in('approve','reject','remove')), reason text not null, created_at timestamptz not null default now());
-- Deny by default: RLS on, no policies. Only the backend (DB owner / service role) can access.
do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table %I enable row level security', t); end loop; end $$;
